1	/**
2	 * @module features/tv-dashboard/ui/TvHero
3	 *
4	 * Hero v3 da Torre de Controle: vendas da rede HOJE + % vs ONTEM
5	 * (comparativo principal; barra de meta pró-rata vira secundária),
6	 * COMPRAS e PERDAS do período do filtro global, contador de alertas
7	 * críticos, relógio + freshness e o FILTRO GLOBAL Hoje/Semana/Mês
8	 * (segmented control glass — muda perdas/compras/comparativos).
9	 *
10	 * v4 (spec tv-acompanhamento-live):
11	 * - navegação ◀ ▶ no histórico (R2) + chip do range exibido + "● Ao vivo";
12	 * - strip do mês (R3+R4): MTD, % da meta mensal, meta da semana corrente
13	 *   (redistribuída) e projeção de fim de mês;
14	 * - botão "Relatório" (R6) abre o modal do relatório matinal.
15	 *
16	 * Linha 1: marca + (freshness · relógio · filtro). Linha 2: métricas.
17	 * Linha 3: strip do mês. Mobile empilha; lg+ vira faixa de zonas.
18	 */
19	
20	import {
21	  ArrowDown,
22	  ArrowUp,
23	  ChevronLeft,
24	  ChevronRight,
25	  FileText,
26	  RefreshCw,
27	  Settings2,
28	} from 'lucide-react';
29	import type {
30	  TvDateRange,
31	  TvFreshness,
32	  TvMonthProgress,
33	  TvNetworkSummary,
34	  TvPeriod,
35	} from '../model/types';
36	import { formatCompactBRL } from '../model/tvMath';
37	import { TvDeltaChip, TvMetaBar } from './TvChips';
38	import {
39	  TV_PERIOD_LABEL,
40	  expectedPctNow,
41	  formatDeltaPct,
42	  formatRangeLabel,
43	  formatTimeHHMM,
44	  metaBarColorFromRatio,
45	  type TvBarColor,
46	} from './tvFormat';
47	import { useCountUp } from './useCountUp';
48	
49	interface TvHeroProps {
50	  network: TvNetworkSummary | null;
51	  freshness: TvFreshness;
52	  now: Date;
53	  /** Período do filtro global (controlado pela página). */
54	  period: TvPeriod;
55	  onPeriodChange: (period: TvPeriod) => void;
56	  /** Offset de navegação no histórico (≤ 0; 0 = ao vivo) — R2. */
57	  offset: number;
58	  onOffsetChange: (offset: number) => void;
59	  /** Range exibido (rótulo do chip no modo histórico). */
60	  range: TvDateRange;
61	  /** Acompanhamento do mês corrente (R3+R4), ou null carregando. */
62	  monthProgress: TvMonthProgress | null;
63	  onMetasClick: () => void;
64	  onReportClick: () => void;
65	}
66	
67	const PERIOD_OPTIONS: ReadonlyArray<{ value: TvPeriod; label: string }> = [
68	  { value: 'today', label: 'Hoje' },
69	  { value: 'week', label: 'Semana' },
70	  { value: 'month', label: 'Mês' },
71	];
72	
73	/** Cor de texto do % da meta semanal a partir da cor semântica da barra. */
74	const WEEK_PCT_TEXT_CLS: Record<TvBarColor, string> = {
75	  sage: 'text-[#57715B]',
76	  amber: 'text-amber-600',
77	  red: 'text-red-600',
78	};
79	
80	/** Segmented control glass do filtro global (Hoje/Semana/Mês). */
81	function TvPeriodFilter({
82	  period,
83	  onPeriodChange,
84	}: {
85	  period: TvPeriod;
86	  onPeriodChange: (period: TvPeriod) => void;
87	}) {
88	  return (
89	    <div
90	      className="inline-flex shrink-0 items-center rounded-full border border-[#57715B]/15 bg-white/60 p-1 backdrop-blur-md"
91	      role="group"
92	      aria-label="Período de perdas, compras e comparativos"
93	      data-testid="tv-period-filter"
94	    >
95	      {PERIOD_OPTIONS.map((opt) => {
96	        const active = opt.value === period;
97	        return (
98	          <button
99	            key={opt.value}
100	            type="button"
101	            aria-pressed={active}
102	            data-mia-action={`filtrar-painel-tv-periodo-${opt.value}`}
103	            onClick={() => onPeriodChange(opt.value)}
104	            className={`rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium leading-none transition-colors motion-reduce:transition-none lg:px-4 lg:py-1.5 ${
105	              active
106	                ? 'bg-[#57715B] text-white shadow-sm'
107	                : 'text-[#5F6F63] hover:bg-[#57715B]/10'
108	            }`}
109	          >
110	            {opt.label}
111	          </button>
112	        );
113	      })}
114	    </div>
115	  );
116	}
117	
118	/**
119	 * Linha de delta vs período anterior (compras/perdas). Neutra por padrão;
120	 * âmbar SÓ no desvio ruim (`amberWhenUp`: perdas subindo). Sem base → texto
121	 * honesto "sem base anterior".
122	 */
123	function TvHeroDeltaLine({
124	  deltaPct,
125	  amberWhenUp = false,
126	}: {
127	  deltaPct: number | null;
128	  amberWhenUp?: boolean;
129	}) {
130	  if (deltaPct == null) {
131	    return (
132	      <span className="font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
133	        sem base anterior
134	      </span>
135	    );
136	  }
137	  const isAmber = amberWhenUp && deltaPct > 0;
138	  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
139	  return (
140	    <span
141	      className={`inline-flex items-center gap-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium tabular-nums ${
142	        isAmber ? 'text-amber-600' : 'text-[#7C887E]'
143	      }`}
144	    >
145	      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
146	      {formatDeltaPct(deltaPct)} vs anterior
147	    </span>
148	  );
149	}
150	
151	/** Strip do mês (R3+R4): MTD, meta mensal, meta da semana e projeção. */
152	function TvHeroMonthStrip({
153	  monthProgress,
154	  now,
155	}: {
156	  monthProgress: TvMonthProgress;
157	  now: Date;
158	}) {
159	  const { mtdTotal, metaMensal, pctMeta, currentWeek, projection } =
160	    monthProgress;
161	
162	  // % do mês decorrido (tick de "esperado agora" da barra mensal)
163	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
164	  const expectedMonthPct = Math.round((now.getDate() / daysInMonth) * 100);
165	  const monthRatio =
166	    pctMeta != null && expectedMonthPct > 0 ? pctMeta / expectedMonthPct : null;
167	  const monthBarColor = metaBarColorFromRatio(monthRatio, now);
168	
169	  // Meta da semana corrente (target redistribuído × realizado)
170	  const weekPct =
171	    currentWeek && currentWeek.target > 0
172	      ? ((currentWeek.achieved ?? 0) / currentWeek.target) * 100
173	      : null;
174	  const weekColor = metaBarColorFromRatio(
175	    weekPct != null ? weekPct / 100 : null,
176	    now,
177	  );
178	
179	  const labelCls =
180	    'font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]';
181	  const valueCls =
182	    'mt-1 font-momma text-[clamp(1.25rem,1.8vw,3.25rem)] font-bold leading-none text-[#2D362E] tabular-nums';
183	
184	  return (
185	    <div
186	      className="grid grid-cols-2 items-start gap-x-4 gap-y-4 border-t border-[#57715B]/10 pt-4 lg:grid-cols-4 lg:gap-8"
187	      data-testid="tv-hero-month-strip"
188	    >
189	      {/* Mês até agora (MTD da rede) */}
190	      <div className="min-w-0">
191	        <span className={labelCls}>MÊS ATÉ AGORA</span>
192	        <p className={valueCls} data-testid="tv-hero-mtd">
193	          {formatCompactBRL(mtdTotal)}
194	        </p>
195	      </div>
196	
197	      {/* % da meta mensal + mini barra (oculto sem meta cadastrada) */}
198	      {metaMensal != null && pctMeta != null ? (
199	        <div className="min-w-0" data-testid="tv-hero-month-goal">
200	          <span className={labelCls}>META MENSAL</span>
201	          <p className={valueCls}>
202	            {Math.round(pctMeta)}%
203	            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
204	              {' '}
205	              de {formatCompactBRL(metaMensal)}
206	            </span>
207	          </p>
208	          <div className="mt-2 max-w-[18rem]">
209	            <TvMetaBar
210	              fillPct={pctMeta}
211	              expectedPct={expectedMonthPct}
212	              color={monthBarColor}
213	              size="card"
214	            />
215	          </div>
216	        </div>
217	      ) : (
218	        <div className="min-w-0" aria-hidden />
219	      )}
220	
221	      {/* Meta da semana corrente (redistribuída — R4) */}
222	      {currentWeek && (
223	        <div className="min-w-0" data-testid="tv-hero-week-goal">
224	          <span className={labelCls}>META DA SEMANA</span>
225	          <p className={valueCls}>
226	            {formatCompactBRL(currentWeek.achieved ?? 0)}
227	            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
228	              {' '}
229	              / {formatCompactBRL(currentWeek.target)}
230	            </span>
231	          </p>
232	          {weekPct != null && (
233	            <p
234	              className={`mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-semibold tabular-nums ${WEEK_PCT_TEXT_CLS[weekColor]}`}
235	            >
236	              {Math.round(weekPct)}% da semana
237	            </p>
238	          )}
239	        </div>
240	      )}
241	
242	      {/* Projeção de fim de mês (run-rate — R3) */}
243	      <div className="min-w-0">
244	        <span className={labelCls}>PROJEÇÃO DO MÊS</span>
245	        <p className={valueCls} data-testid="tv-hero-projection">
246	          {formatCompactBRL(projection)}
247	        </p>
248	      </div>
249	    </div>
250	  );
251	}
252	
253	/** Hero da rede (v4): marca/relógio/filtro + métricas + strip do mês. */
254	export function TvHero({
255	  network,
256	  freshness,
257	  now,
258	  period,
259	  onPeriodChange,
260	  offset,
261	  onOffsetChange,
262	  range,
263	  monthProgress,
264	  onMetasClick,
265	  onReportClick,
266	}: TvHeroProps) {
267	  const vendas = useCountUp(network?.vendasHoje ?? 0);
268	  const hasData = network != null;
269	  const periodLabel = TV_PERIOD_LABEL[period];
270	  const isLive = offset === 0;
271	
272	  // Barra de meta (SECUNDÁRIA na v3): preenchimento = % do dia COMPLETO;
273	  // tick dourado = esperado agora (pró-rata) — só faz sentido AO VIVO.
274	  const fullDayPct =
275	    network && network.metaDia != null && network.metaDia > 0
276	      ? (network.vendasHoje / network.metaDia) * 100
277	      : null;
278	  const expected = expectedPctNow(now);
279	  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
280	  const barColor = metaBarColorFromRatio(ratio, now);
281	
282	  const liveFresh = freshness.vendasLive.level === 'fresh';
283	  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);
284	
285	  const navBtnCls =
286	    'inline-flex shrink-0 items-center justify-center rounded-full border border-[#57715B]/15 bg-white/60 p-1.5 text-[#57715B] backdrop-blur-md transition-colors hover:bg-[#57715B]/10 disabled:cursor-not-allowed disabled:opacity-35 disabled:hover:bg-transparent';
287	
288	  return (
289	    <header
290	      className="flex flex-col gap-4 border-b border-[#C5A065]/25 pb-4 lg:gap-5"
291	      data-testid="tv-hero"
292	    >
293	      {/* Linha 1 — marca + relógio/freshness/filtro global */}
294	      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
295	        <div className="flex min-w-0 flex-col gap-0.5">
296	          <span className="font-momma text-[clamp(0.625rem,0.75vw,1rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
297	            MOMMA
298	          </span>
299	          <span className="font-momma text-[clamp(1.125rem,1.6vw,2.25rem)] font-bold tracking-tight text-[#2D362E] leading-tight">
300	            Painel da Momma
301	          </span>
302	        </div>
303	        <div className="flex flex-wrap items-center gap-x-4 gap-y-2 lg:gap-x-5">
304	          {isLive ? (
305	            /* Indicador live existente (offset 0) */
306	            <span className={`inline-flex items-center gap-2 rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium ${
307	              liveFresh
308	                ? 'bg-emerald-50 text-emerald-600'
309	                : 'border border-amber-400/40 bg-amber-50 text-amber-600'
310	            }`}>
311	              {liveFresh
312	                ? <><span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" aria-hidden />{liveTime ? `atualizado ${liveTime}` : 'ao vivo'}</>
313	                : <><RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />{liveTime ? `atrasado · ${liveTime}` : 'atrasado'}</>
314	              }
315	            </span>
316	          ) : (
317	            /* Modo histórico (R2): chip do range + botão de volta ao vivo */
318	            <span className="inline-flex flex-wrap items-center gap-2">
319	              <span
320	                className="inline-flex items-center rounded-full bg-[#C5A065]/10 px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-semibold tabular-nums text-[#a07c43]"
321	                data-testid="tv-range-chip"
322	              >
323	                {formatRangeLabel(period, range)}
324	              </span>
325	              <button
326	                type="button"
327	                onClick={() => onOffsetChange(0)}
328	                data-mia-action="voltar-painel-tv-ao-vivo"
329	                className="inline-flex items-center gap-2 rounded-full bg-emerald-50 px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium text-emerald-600 transition-colors hover:bg-emerald-100"
330	              >
331	                <span className="h-2 w-2 rounded-full bg-emerald-400" aria-hidden />
332	                Ao vivo
333	              </button>
334	            </span>
335	          )}
336	          <span className="font-momma text-[clamp(1.25rem,2vw,3.75rem)] font-light leading-none text-[#2D362E] tabular-nums">
337	            {formatTimeHHMM(now)}
338	          </span>
339	          {/* Filtro de período com setas ◀ ▶ + botões Metas/Relatório */}
340	          <div className="flex flex-col items-end gap-2">
341	            <div className="flex items-center gap-1.5">
342	              <button
343	                type="button"
344	                onClick={() => onOffsetChange(offset - 1)}
345	                aria-label="Período anterior"
346	                data-mia-action="painel-tv-periodo-anterior"
347	                className={navBtnCls}
348	              >
349	                <ChevronLeft className="h-4 w-4" aria-hidden />
350	              </button>
351	              <TvPeriodFilter period={period} onPeriodChange={onPeriodChange} />
352	              <button
353	                type="button"
354	                onClick={() => onOffsetChange(Math.min(0, offset + 1))}
355	                disabled={offset >= 0}
356	                aria-label="Período seguinte"
357	                data-mia-action="painel-tv-periodo-seguinte"
358	                className={navBtnCls}
359	              >
360	                <ChevronRight className="h-4 w-4" aria-hidden />
361	              </button>
362	            </div>
363	            <div className="flex items-center gap-2">
364	              <button
365	                type="button"
366	                onClick={onMetasClick}
367	                data-mia-action="abrir-metas-painel-tv"
368	                className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 text-sm font-medium text-[#57715B] shadow-sm backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
369	              >
370	                <Settings2 className="h-4 w-4" aria-hidden />
371	                Metas
372	              </button>
373	              <button
374	                type="button"
375	                onClick={onReportClick}
376	                data-mia-action="abrir-relatorio-painel-tv"
377	                className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 text-sm font-medium text-[#57715B] shadow-sm backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
378	              >
379	                <FileText className="h-4 w-4" aria-hidden />
380	                Relatório
381	              </button>
382	            </div>
383	          </div>
384	        </div>
385	      </div>
386	
387	      {/* Linha 2 — métricas: vendas | marketing | perdas */}
388	      <div className="grid grid-cols-2 items-end gap-x-4 gap-y-4 lg:grid-cols-3 lg:gap-8">
389	        {/* Zona 1 — vendas da rede + % vs ontem (principal) */}
390	        <div className="col-span-2 min-w-0 lg:col-span-1">
391	          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
392	            {isLive ? 'REDE · VENDAS HOJE' : `REDE · VENDAS · ${periodLabel.toUpperCase()}`}
393	          </span>
394	          <div className="mt-1 flex flex-wrap items-end gap-x-4 gap-y-2">
395	            <span
396	              className="font-momma text-[clamp(2.25rem,4vw,7.5rem)] font-bold leading-none text-[#2D362E] tabular-nums"
397	              data-testid="tv-hero-sales"
398	            >
399	              {hasData ? formatCompactBRL(vendas) : '—'}
400	            </span>
401	            {network?.deltaOntem != null && (
402	              <span className="pb-1">
403	                <TvDeltaChip
404	                  delta={network.deltaOntem}
405	                  label={isLive ? 'ontem' : 'anterior'}
406	                  size="hero"
407	                />
408	              </span>
409	            )}
410	            {network?.deltaSemana != null && period === 'week' && (
411	              <span className="pb-1">
412	                <TvDeltaChip delta={network.deltaSemana} label="sem. ant." size="hero" />
413	              </span>
414	            )}
415	          </div>
416	          {/* R$/hora · vendas/hora · ticket médio da rede */}
417	          <div className="mt-1.5 flex flex-wrap gap-x-3 gap-y-0.5 font-momma text-[clamp(0.75rem,0.9vw,1.5rem)] tabular-nums">
418	            {network?.valorPorHora != null && (
419	              <span className="whitespace-nowrap font-semibold text-[#5F6F63]">
420	                {formatCompactBRL(network.valorPorHora)}<span className="font-normal text-[#7C887E]">/h</span>
421	              </span>
422	            )}
423	            {network?.vendasPorHora != null && (
424	              <span className="whitespace-nowrap font-semibold text-[#5F6F63]">
425	                {Math.round(network.vendasPorHora)}<span className="font-normal text-[#7C887E]"> vendas/h</span>
426	              </span>
427	            )}
428	            {network?.ticketMedio != null && (
429	              <span className="whitespace-nowrap font-semibold text-[#5F6F63]">
430	                ticket médio <span className="text-[#2D362E]">{formatCompactBRL(network.ticketMedio)}</span>
431	              </span>
432	            )}
433	          </div>
434	          {/* Meta pró-rata — secundária */}
435	          <div className="mt-2 max-w-[36rem]">
436	            <TvMetaBar
437	              fillPct={fullDayPct}
438	              expectedPct={fullDayPct != null && isLive ? expected : null}
439	              color={barColor}
440	              size="card"
441	            />
442	            <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] leading-tight">
443	              {fullDayPct != null ? (
444	                <>
445	                  <span className="font-medium text-[#5F6F63]">
446	                    {Math.round(fullDayPct)}% da meta
447	                  </span>
448	                  {isLive && (
449	                    <span className="text-[#7C887E]"> · esperado {expected}%</span>
450	                  )}
451	                </>
452	              ) : (
453	                <span className="text-[#7C887E]">sem meta cadastrada</span>
454	              )}
455	            </p>
456	          </div>
457	        </div>
458	
459	        {/* Zona 2 — marketing do período */}
460	        <div className="min-w-0">
461	          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
462	            MARKETING · {periodLabel}
463	          </span>
464	          <p
465	            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
466	            data-testid="tv-hero-marketing"
467	          >
468	            {network ? formatCompactBRL(network.marketing.valor) : '—'}
469	          </p>
470	          <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
471	            {network ? `${network.marketing.acoes} ${network.marketing.acoes === 1 ? 'ação' : 'ações'}` : '—'}
472	          </p>
473	        </div>
474	
475	        {/* Zona 3 — perdas do período (R$ + itens; subir é desvio → âmbar) */}
476	        <div className="min-w-0">
477	          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
478	            PERDAS · {periodLabel}
479	          </span>
480	          <p
481	            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
482	            data-testid="tv-hero-perdas"
483	          >
484	            {network ? formatCompactBRL(network.perdas.valor) : '—'}
485	            {network && (
486	              <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
487	                {' '}
488	                · {network.perdas.itens} {network.perdas.itens === 1 ? 'item' : 'itens'}
489	              </span>
490	            )}
491	          </p>
492	          <p className="mt-1">
493	            <TvHeroDeltaLine deltaPct={network?.perdas.deltaPct ?? null} amberWhenUp />
494	          </p>
495	        </div>
496	
497	      </div>
498	
499	      {/* Linha 3 — strip do mês (R3+R4): sempre o mês CORRENTE */}
500	      {monthProgress && <TvHeroMonthStrip monthProgress={monthProgress} now={now} />}
501	    </header>
502	  );
503	}
