1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna vertical de loja — redesign baseado em research de TV dashboards
5	 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
6	 * - Número de vendas é o sinal primário → domina o espaço visualmente
7	 * - Máximo 5 elementos por card para não causar cognitive overload
8	 * - 1 RAG status por card (não 15 células coloridas)
9	 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import { Bike } from 'lucide-react';
14	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
15	import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
16	import { TvDeltaChip, TvLiveIndicator, TvMetaBar, TvRankChip, TvStateChip } from './TvChips';
17	import {
18	  TvColumnBipLine,
19	  TvColumnMetaBar,
20	  TvColumnStockLine,
21	  TvUnitColumn,
22	} from './TvColumnParts';
23	import {
24	  formatTicketBRL,
25	  formatWeekdayDayMonth,
26	  metaBarColorFromRatio,
27	  type TvBarColor,
28	} from './tvFormat';
29	import { useCountUp } from './useCountUp';
30	
31	interface TvStoreColumnProps {
32	  store: TvStoreData;
33	  liveLevel: TvFreshnessLevel;
34	  period: TvPeriod;
35	  now: Date;
36	  rank?: number | null;
37	}
38	
39	/** Coluna de loja — canal Degust live ou Linx defasado. */
40	export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
41	  const { vendas, channel } = store;
42	  const isLive = channel === 'degust-live';
43	  const valorAnim = useCountUp(vendas?.valor ?? 0);
44	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
45	
46	  // Flash dourado ao atualizar o valor de venda
47	  const prevValueRef = useRef(vendas?.valor);
48	  const [flashing, setFlashing] = useState(false);
49	  const flashKeyRef = useRef(0);
50	  useEffect(() => {
51	    if (
52	      vendas?.valor != null &&
53	      prevValueRef.current != null &&
54	      vendas.valor !== prevValueRef.current
55	    ) {
56	      flashKeyRef.current += 1;
57	      setFlashing(true);
58	      const t = window.setTimeout(() => setFlashing(false), 450);
59	      prevValueRef.current = vendas.valor;
60	      return () => window.clearTimeout(t);
61	    }
62	    prevValueRef.current = vendas?.valor;
63	  }, [vendas?.valor]);
64	
65	  // Linha de status: fonte + horário de atualização
66	  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
67	  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;
68	
69	  const showRank = rank != null && rank >= 1 && rank <= 3;
70	
71	  return (
72	    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">
73	
74	      {/* Header: nome + chips de status */}
75	      <div className="flex items-start justify-between gap-2">
76	        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
77	          {store.nome.replace(/^Momma\s+/i, '')}
78	        </h2>
79	        <div className="flex shrink-0 items-center gap-1">
80	          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
81	          <TvStateChip rag={store.rag} />
82	        </div>
83	      </div>
84	
85	      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
86	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
87	        <span
88	          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
89	          className={`font-momma text-3xl font-bold leading-none tabular-nums sm:text-4xl ${
90	            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
91	          }${flashing ? ' tv-value-flash' : ''}`}
92	          data-testid="tv-store-sales"
93	        >
94	          {vendas ? formatCompactBRL(valorAnim) : '—'}
95	        </span>
96	        {store.deltaOntem != null && (
97	          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
98	        )}
99	        {store.deltaSemana != null && period === 'week' && (
100	          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
101	        )}
102	      </div>
103	
104	      {/* R1: quebra Loja × Delivery (só BSB Shopping, período "hoje") —
105	          o número principal acima segue sendo o TOTAL oficial */}
106	      {store.deliverySplit && (
107	        <p
108	          className="mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]"
109	          data-testid="tv-delivery-split"
110	        >
111	          <span className="whitespace-nowrap">
112	            Loja{' '}
113	            <span className="font-medium text-[#5F6F63]">
114	              {formatCompactBRL(store.deliverySplit.balcao)}
115	            </span>
116	          </span>
117	          <span aria-hidden>·</span>
118	          <span className="inline-flex items-center gap-1 whitespace-nowrap">
119	            <Bike className="h-3 w-3 shrink-0 text-[#57715B]" aria-hidden />
120	            Delivery{' '}
121	            <span className="font-medium text-[#5F6F63]">
122	              {formatCompactBRL(store.deliverySplit.delivery)}
123	            </span>
124	          </span>
125	        </p>
126	      )}
127	
128	      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
129	      <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
130	        <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
131	        {isLive
132	          ? updateTime
133	            ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
134	            : 'hoje'
135	          : laggedLabel ?? 'sem dados'}
136	      </p>
137	
138	      {/* Barra de meta do DIA */}
139	      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />
140	
141	      {/* Meta da SEMANA corrente (seg–dom) — linha secundária, não compete
142	          com o número grande de vendas do dia. Ausente quando a loja não
143	          tem meta mensal cadastrada (weeklyGoal null/undefined). */}
144	      {store.weeklyGoal && (
145	        <TvStoreWeeklyGoalLine weeklyGoal={store.weeklyGoal} now={now} />
146	      )}
147	
148	      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
149	      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
150	        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
151	          {vendas?.cupons != null && (
152	            <span className="whitespace-nowrap font-medium">
153	              {vendas.cupons} vendas
154	            </span>
155	          )}
156	          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
157	            <span className="whitespace-nowrap">
158	              {vendas.cupons != null && '· '}
159	              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
160	              <span>/venda</span>
161	            </span>
162	          )}
163	        </div>
164	      )}
165	
166	      {/* Bip + Status de estoque — 1 linha para cada */}
167	      <div className="mt-auto pt-3 space-y-1">
168	        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
169	        <TvColumnStockLine estoque={store.estoque} />
170	      </div>
171	    </TvUnitColumn>
172	  );
173	}
174	
175	/** Cor do % da semana: emerald quando batida; senão mesma régua da barra. */
176	const WEEKLY_PCT_CLS: Record<TvBarColor, string> = {
177	  sage: 'text-[#57715B]',
178	  amber: 'text-amber-600',
179	  red: 'text-red-600',
180	};
181	
182	/**
183	 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
184	 * (cor pela mesma régua da barra diária; emerald quando ≥ 100%) + valores
185	 * compactos "R$ X / R$ Y" + mini barra de progresso ({@link TvMetaBar} mini,
186	 * sem tick de esperado — semana não tem pró-rata intradiário).
187	 */
188	function TvStoreWeeklyGoalLine({
189	  weeklyGoal,
190	  now,
191	}: {
192	  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
193	  now: Date;
194	}) {
195	  const { target, achieved, pct } = weeklyGoal;
196	  const beaten = pct != null && pct >= 100;
197	  const barColor: TvBarColor = beaten
198	    ? 'sage'
199	    : metaBarColorFromRatio(pct != null ? pct / 100 : null, now);
200	  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];
201	
202	  return (
203	    <div className="mt-2" data-testid="tv-weekly-goal">
204	      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
205	        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
206	          SEMANA
207	        </span>
208	        <span className="min-w-0 truncate text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
209	          <span
210	            className={`text-xs font-bold tabular-nums ${pctCls}`}
211	            data-testid="tv-weekly-goal-pct"
212	          >
213	            {pct != null ? `${Math.round(pct)}%` : '—'}
214	          </span>{' '}
215	          {formatCompactBRL(achieved)} / {formatCompactBRL(target)}
216	        </span>
217	      </div>
218	      <div className="mt-1">
219	        <TvMetaBar fillPct={pct} expectedPct={null} color={barColor} size="mini" />
220	      </div>
221	    </div>
222	  );
223	}
