1	/**
2	 * @module features/tv-dashboard/ui/tvFormat
3	 *
4	 * Formatadores de APRESENTAÇÃO do Painel TV (camada UI).
5	 * Regras de negócio/agregação vivem em `../model/tvMath` — aqui só render.
6	 */
7	
8	import type { TvDateRange, TvPeriod } from '../model/types';
9	import { businessDayFraction, parseIsoDateLocal } from '../model/tvMath';
10	
11	/** Cor semântica da barra de meta (design.md §1.6 — estado de VENDA). */
12	export type TvBarColor = 'sage' | 'amber' | 'red';
13	
14	/** Rótulo pt-BR do filtro global de período (hero + colunas, v3). */
15	export const TV_PERIOD_LABEL: Record<TvPeriod, string> = {
16	  today: 'hoje',
17	  week: 'semana',
18	  month: 'mês',
19	};
20	
21	/** Abreviações pt-BR dos dias da semana (índice = `Date.getDay()`). */
22	export const WEEKDAY_ABBR = [
23	  'dom.',
24	  'seg.',
25	  'ter.',
26	  'qua.',
27	  'qui.',
28	  'sex.',
29	  'sáb.',
30	] as const;
31	
32	/** Hora local `HH:MM` (sem segundos — design.md §1.5), ou null sem dado. */
33	export function formatTimeHHMM(value: Date | string | null | undefined): string | null {
34	  if (value == null) return null;
35	  const d = value instanceof Date ? value : new Date(value);
36	  if (Number.isNaN(d.getTime())) return null;
37	  return d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
38	}
39	
40	/** Contagem inteira com separador de milhar pt-BR ("1.240"). */
41	export function formatInt(value: number): string {
42	  return Math.round(value).toLocaleString('pt-BR');
43	}
44	
45	/**
46	 * Quantidade de estoque/movimentação: inteiro seco ("12") ou com até 1
47	 * decimal pt-BR quando fracionada ("2,5") — nunca arredonda silenciosamente
48	 * um fracionado para inteiro.
49	 */
50	export function formatQty(value: number): string {
51	  return value.toLocaleString('pt-BR', {
52	    minimumFractionDigits: 0,
53	    maximumFractionDigits: 1,
54	  });
55	}
56	
57	/** Ticket médio sempre com 2 decimais ("R$ 38,50" — design.md §1.5). */
58	export function formatTicketBRL(value: number): string {
59	  return `R$ ${value.toLocaleString('pt-BR', {
60	    minimumFractionDigits: 2,
61	    maximumFractionDigits: 2,
62	  })}`;
63	}
64	
65	/** Delta com sinal e seta textual implícita ("12%" — sinal vem do ícone). */
66	export function formatDeltaPct(delta: number): string {
67	  return `${Math.abs(Math.round(delta))}%`;
68	}
69	
70	/** Rótulo "ter. 03/06" para o dia de referência de canal defasado. */
71	export function formatWeekdayDayMonth(date: Date): string {
72	  const dd = String(date.getDate()).padStart(2, '0');
73	  const mm = String(date.getMonth() + 1).padStart(2, '0');
74	  return `${WEEKDAY_ABBR[date.getDay()]} ${dd}/${mm}`;
75	}
76	
77	/** Abreviações pt-BR dos meses (índice = `Date.getMonth()`). */
78	export const MONTH_ABBR = [
79	  'jan',
80	  'fev',
81	  'mar',
82	  'abr',
83	  'mai',
84	  'jun',
85	  'jul',
86	  'ago',
87	  'set',
88	  'out',
89	  'nov',
90	  'dez',
91	] as const;
92	
93	/**
94	 * Rótulo do range exibido no modo histórico (chip do hero, R2):
95	 * - dia: "ter. 10/06";
96	 * - semana: "02–08/06" (mês duplicado quando a semana cruza meses);
97	 * - mês: "mai/2026".
98	 */
99	export function formatRangeLabel(period: TvPeriod, range: TvDateRange): string {
100	  const from = parseIsoDateLocal(range.from);
101	  const to = parseIsoDateLocal(range.to);
102	  if (period === 'today') return formatWeekdayDayMonth(from);
103	  if (period === 'week') {
104	    const dd = (d: Date) => String(d.getDate()).padStart(2, '0');
105	    const mm = (d: Date) => String(d.getMonth() + 1).padStart(2, '0');
106	    return from.getMonth() === to.getMonth()
107	      ? `${dd(from)}–${dd(to)}/${mm(to)}`
108	      : `${dd(from)}/${mm(from)}–${dd(to)}/${mm(to)}`;
109	  }
110	  return `${MONTH_ABBR[from.getMonth()]}/${from.getFullYear()}`;
111	}
112	
113	/** "há 12 min" / "há 3h" para timestamps recentes; null sem dado. */
114	export function formatAgoLabel(
115	  value: Date | string | null | undefined,
116	  now: Date,
117	): string | null {
118	  if (value == null) return null;
119	  const d = value instanceof Date ? value : new Date(value);
120	  if (Number.isNaN(d.getTime())) return null;
121	  const diffMin = Math.max(0, Math.floor((now.getTime() - d.getTime()) / 60_000));
122	  if (diffMin < 60) return `há ${diffMin} min`;
123	  return `há ${Math.floor(diffMin / 60)}h`;
124	}
125	
126	/**
127	 * Cor da barra de % meta a partir do ratio pró-rata (`%real / %esperado`,
128	 * em fração: 1.0 = exatamente no ritmo). Regra do design.md §1.6:
129	 * sage ≥ 0,9 · âmbar 0,75–0,9 · vermelho abaixo de 0,6 após 12:00
130	 * (entre 0,6 e 0,75 fica âmbar).
131	 * Ratio nulo (sem meta / antes da janela) fica sage — barra neutra.
132	 */
133	export function metaBarColorFromRatio(ratio: number | null, now: Date): TvBarColor {
134	  if (ratio == null) return 'sage';
135	  if (ratio >= 0.9) return 'sage';
136	  if (ratio >= 0.75) return 'amber';
137	  if (ratio < 0.6 && now.getHours() >= 12) return 'red';
138	  return 'amber';
139	}
140	
141	/** % esperado AGORA da meta do dia (posição do tick pró-rata), 0–100. */
142	export function expectedPctNow(now: Date): number {
143	  return Math.round(businessDayFraction(now) * 100);
144	}
145	
146	/** Limita um percentual de preenchimento de barra ao intervalo [0, 100]. */
147	export function clampPct(pct: number | null): number {
148	  if (pct == null || Number.isNaN(pct)) return 0;
149	  return Math.max(0, Math.min(100, pct));
150	}
151

1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	  TvStoreWeeklyGoal,
24	  TvWeekSegment,
25	  TvWeeklyGoal,
26	} from './types';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Constantes de negócio
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/**
33	 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
34	 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
35	 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
36	 */
