582	// ─────────────────────────────────────────────────────────────────────────────
583	// RAG da loja
584	// ─────────────────────────────────────────────────────────────────────────────
585	
586	/** Entrada da classificação RAG de uma unidade. */
587	export interface StoreRagInput {
588	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
589	  stockOutCount: number;
590	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
591	  stockLowCount: number;
592	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
593	  pctMetaProRata: number | null;
594	  /** true quando a unidade tem venda ao vivo (canal Degust). */
595	  isLiveChannel: boolean;
596	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
597	  lastMovementAt: Date | string | null;
598	  /** Instante da avaliação. */
599	  now: Date;
600	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
601	  hours?: TvBusinessHours;
602	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
603	  noMovementThresholdHours?: number;
604	}
605	
606	/**
607	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
608	 *
609	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
610	 *   não faz sentido alertar madrugada sem bipagem.
611	 * - A referência é clampada ao início da janela de hoje: se a última
612	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
613	 */
614	export function hoursWithoutMovementInWindow(
615	  lastMovementAt: Date | string | null,
616	  now: Date,
617	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
618	): number | null {
619	  const fraction = businessDayFraction(now, hours);
620	  if (fraction <= 0 || fraction >= 1) return null;
621	  const windowStart = new Date(now);
622	  windowStart.setHours(hours.start, 0, 0, 0);
623	  const last = lastMovementAt
624	    ? new Date(lastMovementAt).getTime()
625	    : Number.NEGATIVE_INFINITY;
626	  const ref = Math.max(last, windowStart.getTime());
627	  return (now.getTime() - ref) / 3_600_000;
628	}
629	
630	/**
631	 * Classificação RAG de uma unidade (management-by-exception).
632	 *
633	 * Regras (design.md §1.6, ordem de precedência):
634	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
635	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
636	 *   manhã, quando o pró-rata ainda é instável).
637	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
638	 *   movimentação há mais que o threshold dentro da janela OU venda live com
639	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
640	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
641	 *   em canal live e com meta cadastrada (pct != null).
642	 * - OK: nenhum desvio — tela calma, sem cor.
643	 */
644	export function classifyStoreRag(input: StoreRagInput): {
645	  status: TvRagStatus;
646	  reasons: string[];
647	} {
648	  const hours = input.hours ?? TV_BUSINESS_HOURS;
649	  const noMovementThreshold =
650	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
651	  const reasons: string[] = [];
652	
653	  // ── Vermelho: só ruptura (item zerado em alerta) ──
654	  if (input.stockOutCount > 0) {
655	    reasons.push(
656	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
657	    );
658	    return { status: 'red', reasons };
659	  }
660	
661	  // ── Âmbar ──
662	  if (input.stockLowCount > 0) {
663	    reasons.push(
664	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
665	    );
666	  }
667	  const gapHours = hoursWithoutMovementInWindow(
668	    input.lastMovementAt,
669	    input.now,
670	    hours,
671	  );
672	  if (gapHours !== null && gapHours > noMovementThreshold) {
673	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
674	  }
675	  if (
676	    input.isLiveChannel &&
677	    input.pctMetaProRata !== null &&
678	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
679	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
680	  ) {
681	    reasons.push(
682	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
683	    );
684	  }
685	  if (reasons.length > 0) return { status: 'amber', reasons };
686	
687	  return { status: 'ok', reasons: [] };
688	}
