940	/**
941	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
942	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
943	 * query). Regras (critério existente do projeto, sem schema novo):
944	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
945	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
946	 *   normalizada client-side porque a caixa no banco é inconsistente;
947	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
948	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
949	 */
950	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
951	  const out = new Map<number, StockDetail>();
952	  for (const row of rows) {
953	    if (row.loja_id == null) continue;
954	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
955	    const min = row.quantidade_minima ?? 0;
956	    if (min <= 0) continue; // sem mínimo definido → sem alerta
957	    const qty = row.quantidade_atual ?? 0;
958	    if (qty >= min) continue; // dentro do normal
959	    let detail = out.get(row.loja_id);
960	    if (!detail) {
961	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
962	      out.set(row.loja_id, detail);
963	    }
964	    const zerado = qty <= 0;
965	    if (zerado) detail.zerados += 1;
966	    else detail.abaixoMinimo += 1;
967	    detail.itens.push({
968	      produtoNome: row.produtoNome,
969	      quantidade: qty,
970	      quantidadeMinima: min,
971	      zerado,
972	    });
973	  }
974	  return out;
975	}
