1018	/**
1019	 * Corrige o `loja_id` das linhas de flash-vendas.
1020	 *
1021	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
1022	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
1023	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
1024	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
1025	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
1026	 *
1027	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
1028	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
1029	 * - Caso contrário → descarta (não corromper outra loja).
1030	 */
1031	export function remapFlashLojaIds(
1032	  rows: FlashRow[],
1033	  degustCodeToLoja: ReadonlyMap<number, number>,
1034	  knownDegustLojaIds: ReadonlySet<number>,
1035	): FlashRow[] {
1036	  const out: FlashRow[] = [];
1037	  for (const row of rows) {
1038	    if (knownDegustLojaIds.has(row.loja_id)) {
1039	      out.push(row);
1040	      continue;
1041	    }
1042	    const mapped = degustCodeToLoja.get(row.loja_id);
1043	    if (mapped != null) {
1044	      out.push({ ...row, loja_id: mapped });
1045	    }
1046	    // não mapeável → descartado de propósito (ver TSDoc)
1047	  }
1048	  return out;
1049	}
