1151	    let agg = byLoja.get(row.loja_id);
1152	    if (!agg) {
1153	      agg = { valor: 0, acoes: 0 };
1154	      byLoja.set(row.loja_id, agg);
1155	    }
1156	    agg.valor += valor;
1157	    agg.acoes += 1;
1158	  }
1159	  return { byLoja, total };
1160	}
