1171	/** Converte uma linha crua do feed em {@link TvRecentMove} exibível. */
1172	export function mapFeedRow(row: MovementFeedRow): TvRecentMove {
1173	  return {
1174	    hora: timeHHMMFromIso(row.data_movimentacao),
1175	    timestamp: row.data_movimentacao,
1176	    tipo: row.tipo_movimentacao,
1177	    produtoNome: row.produtoNome,
1178	    quantidade: row.quantidade ?? 0,
1179	  };
