1182	/**
1183	 * Agrupa o feed (já ordenado DESC por `data_movimentacao` na query) por
1184	 * loja, mantendo as `perStore` primeiras linhas de cada uma (mini-feed
1185	 * "AGORA"). Linhas sem loja são ignoradas. NÃO reordena — confia na
1186	 * ordenação da query (única fonte do "mais recente primeiro").
1187	 */
1188	export function buildRecentMoves(
1189	  rows: MovementFeedRow[],
1190	  perStore: number = TV_MINI_FEED_SIZE,
1191	): Map<number, TvRecentMove[]> {
1192	  const out = new Map<number, TvRecentMove[]>();
1193	  for (const row of rows) {
1194	    if (row.loja_id == null) continue;
1195	    let list = out.get(row.loja_id);
1196	    if (!list) {
1197	      list = [];
1198	      out.set(row.loja_id, list);
1199	    }
1200	    if (list.length >= perStore) continue;
1201	    list.push(mapFeedRow(row));
1202	  }
1203	  return out;
1204	}
