1206	// ─────────────────────────────────────────────────────────────────────────────
1207	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
1208	// ─────────────────────────────────────────────────────────────────────────────
1209	
1210	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1211	export interface TvPageResult<T> {
1212	  data: T[] | null;
1213	  error: { message: string } | null;
1214	}
1215	
1216	/**
1217	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1218	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1219	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1220	 *
1221	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1222	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1223	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1224	 * sobreporem entre requests.
1225	 */
1226	export async function fetchAllPages<T>(
1227	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1228	  pageSize = 1000,
1229	): Promise<T[]> {
1230	  const all: T[] = [];
1231	  let offset = 0;
1232	  for (;;) {
1233	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1234	    if (error) throw error;
1235	    const rows = data ?? [];
1236	    all.push(...rows);
1237	    if (rows.length < pageSize) return all;
1238	    offset += pageSize;
1239	  }
1240	}
