1	/**
2	 * @module features/tv-dashboard/model/useTvReport
3	 *
4	 * Dados do RELATÓRIO MATINAL (R6 da spec `tv-acompanhamento-live`):
5	 * uma única chamada à edge `degust-pos-financial` cobrindo o mês do
6	 * dia-base (01 → dia-base, com quebra delivery do BSB) + `metas_mensais`
7	 * do mês. Deriva: faturamento do dia-base por loja e rede, MTD por loja
8	 * e rede, meta mensal + %, meta/realizado da semana corrente
9	 * (redistribuição de `weeklyTargets`) e projeção de fim de mês.
10	 *
11	 * SEM polling: o relatório é um snapshot sob demanda (modal aberto).
12	 * `buildTvReportText` é pura — testável sem I/O.
13	 */
14	
15	import { useQuery } from '@tanstack/react-query';
16	import { supabase } from '@/integrations/supabase/client';
17	import {
18	  TV_DELIVERY_SPLIT_LOJA_ID,
19	  monthEndProjection,
20	  parseIsoDateLocal,
21	  toIsoDateLocal,
22	  weeklyTargets,
23	} from './tvMath';
24	import type { TvWeeklyGoal } from './types';
25	import { fetchTvContext, tvDashboardKeys } from './useTvDashboardData';
26	
27	// ─────────────────────────────────────────────────────────────────────────────
28	// Tipos
29	// ─────────────────────────────────────────────────────────────────────────────
30	
31	/** Linha por loja do relatório (dia-base + acumulado do mês). */
32	export interface TvReportLojaLine {
33	  lojaId: number;
34	  /** Nome curto (sem o prefixo "Momma "). */
35	  nome: string;
36	  /** R$ do dia-base (null = sem venda registrada no dia → "—"). */
37	  valorDia: number | null;
38	  /** R$ acumulado 01 → dia-base. */
39	  mtd: number;
40	}
41	
42	/** Snapshot derivado do relatório matinal. */
43	export interface TvReportData {
44	  /** Dia-base (YYYY-MM-DD). */
45	  baseDate: string;
46	  /** R$ da rede no dia-base. */
47	  totalDia: number;
48	  /** R$ da rede acumulado 01 → dia-base. */
49	  totalMtd: number;
50	  /** Lojas Degust ordenadas por faturamento do dia desc (sem venda no fim). */
51	  lojas: TvReportLojaLine[];
52	  /** Quebra do BSB Shopping no dia-base (null sem cupom delivery). */
53	  deliverySplit: { delivery: number; balcao: number } | null;
54	  /** Meta mensal da rede (linha NULL; fallback soma por loja), ou null. */
55	  metaMensal: number | null;
56	  /** % da meta mensal já realizada, ou null sem meta. */
57	  pctMeta: number | null;
58	  /** Semana corrente (contendo o dia-base) com meta redistribuída, ou null. */
59	  currentWeek: TvWeeklyGoal | null;
60	  /** Projeção de fim de mês por run-rate até o dia-base. */
61	  projection: number;
62	}
63	
64	/** Resposta da edge `degust-pos-financial` (campos usados no relatório). */
65	interface DegustReportResponse {
66	  daily?: Array<{
67	    data: string;
68	    loja_id: number;
69	    total_faturado: number;
70	    total_cupons: number;
71	  }>;
72	  deliverySplit?: Array<{
73	    data: string;
74	    loja_id: number;
75	    total_delivery: number;
76	    cupons_delivery: number;
77	  }>;
78	}
79	
80	// ─────────────────────────────────────────────────────────────────────────────
81	// Fetch + derivação
82	// ─────────────────────────────────────────────────────────────────────────────
83	
84	async function fetchTvReport(baseDateIso: string): Promise<TvReportData> {
85	  const base = parseIsoDateLocal(baseDateIso);
86	  const monthStart = toIsoDateLocal(
87	    new Date(base.getFullYear(), base.getMonth(), 1),
88	  );
89	
90	  const ctx = await fetchTvContext();
91	  const [edgeRes, metasRes] = await Promise.all([
92	    supabase.functions.invoke('degust-pos-financial', {
93	      body: {
94	        startDate: monthStart,
95	        endDate: baseDateIso,
96	        includeDeliverySplit: true,
97	        deliveryLojaId: TV_DELIVERY_SPLIT_LOJA_ID,
98	      },
99	    }),
100	    supabase
101	      .from('metas_mensais')
102	      .select('loja_id, valor_meta')
103	      .eq('ano', base.getFullYear())
104	      .eq('mes', base.getMonth() + 1),
105	  ]);
106	  if (edgeRes.error) {
107	    throw new Error(
108	      `[tv-report] degust-pos-financial: ${edgeRes.error.message ?? 'falha na edge'}`,
109	    );
110	  }
111	  const edge = (edgeRes.data ?? {}) as DegustReportResponse;
112	  // Meta ausente não derruba o relatório (mesma tolerância do painel)
113	  const metasRows = metasRes.error ? [] : (metasRes.data ?? []);
114	
115	  // Agregações: dia-base por loja, MTD por loja e por data (rede)
116	  const dayByLoja = new Map<number, number>();
117	  const mtdByLoja = new Map<number, number>();
118	  const redeByDate = new Map<string, number>();
119	  for (const d of edge.daily ?? []) {
120	    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
121	    if (d.data > baseDateIso) continue;
122	    const valor = d.total_faturado ?? 0;
123	    mtdByLoja.set(d.loja_id, (mtdByLoja.get(d.loja_id) ?? 0) + valor);
124	    redeByDate.set(d.data, (redeByDate.get(d.data) ?? 0) + valor);
125	    if (d.data === baseDateIso) {
126	      dayByLoja.set(d.loja_id, (dayByLoja.get(d.loja_id) ?? 0) + valor);
127	    }
128	  }
129	  let totalDia = 0;
130	  for (const v of dayByLoja.values()) totalDia += v;
131	  let totalMtd = 0;
132	  for (const v of mtdByLoja.values()) totalMtd += v;
133	
134	  // Linhas por loja (Degust), ordenadas por faturamento do dia desc;
135	  // lojas sem venda no dia ("—") vão pro fim, ordenadas por MTD.
136	  const lojas: TvReportLojaLine[] = ctx.lojas
137	    .filter((l) => ctx.degustLojaIds.has(l.id))
138	    .map((l) => ({
139	      lojaId: l.id,
140	      nome: l.nome.replace(/^Momma\s+/i, ''),
141	      valorDia: dayByLoja.has(l.id) ? (dayByLoja.get(l.id) ?? 0) : null,
142	      mtd: mtdByLoja.get(l.id) ?? 0,
143	    }))
144	    .sort((a, b) => (b.valorDia ?? -1) - (a.valorDia ?? -1) || b.mtd - a.mtd);
145	
146	  // Quebra delivery do BSB no dia-base (balcão = total oficial − delivery)
147	  const splitRow = (edge.deliverySplit ?? []).find(
148	    (r) => r.data === baseDateIso && r.loja_id === TV_DELIVERY_SPLIT_LOJA_ID,
149	  );
150	  const bsbDia = dayByLoja.get(TV_DELIVERY_SPLIT_LOJA_ID);
151	  const deliverySplit =
152	    splitRow != null && bsbDia != null
153	      ? {
154	          delivery: splitRow.total_delivery,
155	          balcao: Math.max(0, bsbDia - splitRow.total_delivery),
156	        }
157	      : null;
158	
159	  // Meta mensal: linha da rede (loja_id NULL); fallback = soma por loja
160	  const redeRow = metasRows.find((m) => m.loja_id === null);
161	  const lojaRows = metasRows.filter((m) => m.loja_id !== null);
162	  const metaMensal =
163	    redeRow != null
164	      ? redeRow.valor_meta
165	      : lojaRows.length > 0
166	        ? lojaRows.reduce((s, m) => s + m.valor_meta, 0)
167	        : null;
168	
169	  // Semana corrente (contendo o dia-base) com redistribuição (R4)
170	  const weeks =
171	    metaMensal != null && metaMensal > 0
172	      ? weeklyTargets(metaMensal, redeByDate, base)
173	      : [];
174	
175	  return {
176	    baseDate: baseDateIso,
177	    totalDia,
178	    totalMtd,
179	    lojas,
180	    deliverySplit,
181	    metaMensal,
182	    pctMeta:
183	      metaMensal != null && metaMensal > 0 ? (totalMtd / metaMensal) * 100 : null,
184	    currentWeek: weeks.find((w) => w.isCurrent) ?? null,
185	    projection: monthEndProjection(totalMtd, base),
186	  };
187	}
188	
189	// ─────────────────────────────────────────────────────────────────────────────
190	// Texto do relatório (pura — formato pt-BR pronto pra WhatsApp)
191	// ─────────────────────────────────────────────────────────────────────────────
192	
193	/** R$ inteiro pt-BR ("R$ 9.999") — relatório não usa centavos. */
194	function brl(value: number): string {
195	  return `R$ ${Math.round(value).toLocaleString('pt-BR')}`;
196	}
197	
198	/** "quarta, 10/06/2026" (weekday longo sem o sufixo "-feira"). */
199	function formatLongDate(date: Date): string {
200	  const weekday = date
201	    .toLocaleDateString('pt-BR', { weekday: 'long' })
202	    .replace('-feira', '');
203	  return `${weekday}, ${date.toLocaleDateString('pt-BR')}`;
204	}
205	
206	/**
207	 * Monta o texto do relatório matinal (R6). `todayIso` injetável para
208	 * teste: define se o dia-base é "ontem" (rótulo padrão do relatório)
209	 * ou outro dia ("Faturamento do dia").
210	 */
211	export function buildTvReportText(
212	  report: TvReportData,
213	  todayIso: string = toIsoDateLocal(new Date()),
214	): string {
215	  const base = parseIsoDateLocal(report.baseDate);
216	  const yesterdayOfToday = toIsoDateLocal(
217	    new Date(parseIsoDateLocal(todayIso).getTime() - 86_400_000),
218	  );
219	  const isYesterday = report.baseDate === yesterdayOfToday;
220	  const dd = String(base.getDate()).padStart(2, '0');
221	  const mm = String(base.getMonth() + 1).padStart(2, '0');
222	
223	  const lines: string[] = [];
224	  lines.push('📊 *Momma — Relatório Diário*');
225	  lines.push(`🗓 ${formatLongDate(base)}`);
226	  lines.push('');
227	  lines.push(
228	    `*Faturamento ${isYesterday ? 'de ontem' : 'do dia'}:* ${brl(report.totalDia)}`,
229	  );
230	  for (const loja of report.lojas) {
231	    let line = `• ${loja.nome}: ${loja.valorDia != null ? brl(loja.valorDia) : '—'}`;
232	    if (
233	      loja.lojaId === TV_DELIVERY_SPLIT_LOJA_ID &&
234	      report.deliverySplit != null &&
235	      loja.valorDia != null
236	    ) {
237	      line += ` (loja ${brl(report.deliverySplit.balcao)} · delivery ${brl(report.deliverySplit.delivery)})`;
238	    }
239	    lines.push(line);
240	  }
241	  lines.push('');
242	  const metaPart =
243	    report.pctMeta != null && report.metaMensal != null
244	      ? ` • ${Math.round(report.pctMeta)}% da meta de ${brl(report.metaMensal)}`
245	      : '';
246	  lines.push(`*Mês (01–${dd}/${mm}):* ${brl(report.totalMtd)}${metaPart}`);
247	  for (const loja of [...report.lojas].sort((a, b) => b.mtd - a.mtd)) {
248	    lines.push(`• ${loja.nome}: ${loja.mtd > 0 ? brl(loja.mtd) : '—'}`);
249	  }
250	  lines.push('');
251	  if (report.currentWeek) {
252	    const pct =
253	      report.currentWeek.target > 0
254	        ? Math.round(
255	            ((report.currentWeek.achieved ?? 0) / report.currentWeek.target) * 100,
256	          )
257	        : 0;
258	    lines.push(
259	      `*Semana atual:* ${brl(report.currentWeek.achieved ?? 0)} / meta ${brl(report.currentWeek.target)} (${pct}%)`,
260	    );
261	  }
262	  lines.push(`*Projeção fim do mês:* ${brl(report.projection)}`);
263	  return lines.join('\n');
264	}
265	
266	// ─────────────────────────────────────────────────────────────────────────────
267	// Hook
268	// ─────────────────────────────────────────────────────────────────────────────
269	
270	/**
271	 * Snapshot do relatório matinal para o dia-base. UMA chamada à edge por
272	 * dia-base (sem polling — `staleTime` longo; refetch só por troca de data
273	 * ou reabertura após GC do cache).
274	 *
275	 * @param baseDateIso - Dia-base (YYYY-MM-DD), tipicamente ontem.
276	 * @param enabled - true apenas com o modal aberto (não busca à toa).
277	 */
278	export function useTvReport(baseDateIso: string, enabled: boolean) {
279	  return useQuery({
280	    queryKey: [...tvDashboardKeys.all, 'report', baseDateIso] as const,
281	    queryFn: () => fetchTvReport(baseDateIso),
282	    enabled,
283	    staleTime: 5 * 60_000,
284	    refetchInterval: false,
285	    refetchOnWindowFocus: false,
286	  });
287	}
