59	
60	const COL_ENTER_CLS = [
61	  'tv-col-enter tv-col-enter-1',
62	  'tv-col-enter tv-col-enter-2',
63	  'tv-col-enter tv-col-enter-3',
64	  'tv-col-enter tv-col-enter-4',
65	  'tv-col-enter tv-col-enter-5',
66	  'tv-col-enter tv-col-enter-6',
67	] as const;
68	
69	/** Página raiz do painel TV — Torre de Controle da Operação. */
70	export default function TvDashboardPage() {
71	  const navigate = useNavigate();
72	  const [period, setPeriod] = useState<TvPeriod>('today');
73	  // Navegação no histórico (R2): 0 = ao vivo; −n = período completo n atrás
74	  const [offset, setOffset] = useState(0);
75	  const [reportOpen, setReportOpen] = useState(false);
76	
77	  // Trocar de período SEMPRE volta ao período corrente (offset 0)
78	  const handlePeriodChange = useCallback((next: TvPeriod) => {
79	    setPeriod(next);
80	    setOffset(0);
81	  }, []);
82	  const handleOffsetChange = useCallback((next: number) => {
83	    setOffset(Math.min(0, next));
84	  }, []);
85	
86	  useEffect(() => {
87	    document.title = 'Painel da Momma';
88	    return () => { document.title = 'MommaERP'; };
89	  }, []);
90	  const data = useTvDashboardData(period, offset);
91	  useTvRealtime();
92	  const now = useMinuteClock();
93	
94	  const rankedStores = useMemo(() => {
95	    if (!data.stores) return [] as typeof data.stores;
96	    return data.stores.map((s, _, arr) => {
97	      const vendas = s.vendas?.valor ?? 0;
98	      const rank =
99	        vendas > 0 ? arr.filter((x) => (x.vendas?.valor ?? 0) > vendas).length + 1 : null;
100	      return { ...s, rank };
101	    });
102	  }, [data.stores]);
103	
104	  if (data.isLoading) {
105	    return (
106	      <MommaPageLayout>
107	        <div className="p-4 sm:p-6 space-y-4 font-momma">
108	          <div className="h-32 rounded-2xl bg-white/60 backdrop-blur-xl border border-[#57715B]/10 animate-pulse" />
109	          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
110	            {Array.from({ length: 6 }, (_, i) => (
111	              <TvColumnSkeleton key={i} delay={i * 60} />
112	            ))}
113	          </div>
114	        </div>
115	      </MommaPageLayout>
116	    );
117	  }
118	
119	  const storeCards = rankedStores.slice(0, data.factory ? 5 : 6);
