183	/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
184	export async function fetchTvContext(): Promise<TvContext> {
185	  const [lojasRes, degustRes] = await Promise.all([
186	    supabase
187	      .from('lojas')
188	      .select('id, nome, tipo')
189	      .eq('ativo', true)
190	      .order('id'),
191	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
192	  ]);
193	  if (lojasRes.error) throw lojasRes.error;
194	  if (degustRes.error) throw degustRes.error;
195	
196	  const lojas: TvLoja[] = lojasRes.data ?? [];
197	  const degustLojaIds = new Set<number>();
198	  const degustCodeToLoja = new Map<number, number>();
199	  for (const row of degustRes.data ?? []) {
200	    degustLojaIds.add(row.loja_id);
201	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
202	  }
203	
204	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
205	  const linxLojaIds = lojas
206	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
207	    .map((l) => l.id);
208	
209	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
210	}
