/**
 * Fração ESPERADA da semana corrente já decorrida em `now` — análoga ao
 * `expectedMonthPct` da barra mensal (dias inteiros; HOJE conta inteiro,
 * mesmo padrão de `now.getDate() / daysInMonth`). A "semana" é o segmento
 * seg-dom do mês CORRENTE recortado por {@link monthWeekSegments} (mesmo
 * recorte de {@link weeklyTargets}/{@link currentWeekGoal}).
 *
 * Uso: pace-ajustar a COR da meta semanal (`ratio = %real / %esperado`),
 * consistente com a barra mensal — começo de semana no ritmo NÃO fica
 * vermelho. O % numérico exibido segue sendo o real (achieved/target).
 *
 * Retorna 1 se `now` não cair em nenhum segmento (defensivo — na prática
 * todo dia do mês pertence a um segmento).
 */
export function expectedWeekFraction(now: Date): number {
  const todayIso = toIsoDateLocal(now);
  const segment = monthWeekSegments(now.getFullYear(), now.getMonth()).find(
    (s) => s.from <= todayIso && todayIso <= s.to,
  );
  if (!segment) return 1;
  // Math.round absorve a hora de DST (diferença 23h/25h em viradas)
  const elapsedDays =
    Math.round(
      (parseIsoDateLocal(todayIso).getTime() -
        parseIsoDateLocal(segment.from).getTime()) /
        86_400_000,
    ) + 1;
  return Math.min(1, elapsedDays / segment.days);
}

